"use strict";
(() => {
  const PLATFORMS=["tiktok","twitch","cng","youtube"];
  const MOD_KEY="batto-moderation-v1";
  const TIKFINITY_URL="ws://127.0.0.1:21213/";
  let selectedPlatform="tiktok";
  let tikfinity=null;
  let tikfinityConnected=false;

  const esc=v=>String(v??"").replace(/[&<>\"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const cleanUser=v=>String(v||"").trim().replace(/^@/,"").slice(0,80);
  function emptyPlatform(){return{moderators:[],muted:[],blocked:[],audit:[]};}
  function loadMod(){try{const v=JSON.parse(localStorage.getItem(MOD_KEY)||"{}");for(const p of PLATFORMS)if(!v[p])v[p]=emptyPlatform();return v;}catch{return Object.fromEntries(PLATFORMS.map(p=>[p,emptyPlatform()]));}}
  let mod=loadMod();
  function saveMod(){localStorage.setItem(MOD_KEY,JSON.stringify(mod));renderModeration();}
  function entryIndex(list,user){return list.findIndex(x=>x.username.toLowerCase()===user.toLowerCase());}
  function addAudit(platform,username,action,reason,lastMessage,result="Lokal"){const p=mod[platform]||(mod[platform]=emptyPlatform());p.audit.unshift({time:new Date().toISOString(),username,action,reason:reason||"",lastMessage:lastMessage||"",by:"Crazy_Batto",result});p.audit=p.audit.slice(0,500);}
  function applyModeration(platform,username,action,lastMessage){platform=PLATFORMS.includes(platform)?platform:"tiktok";username=cleanUser(username);if(!username)return;const p=mod[platform]||(mod[platform]=emptyPlatform());let reason="";
    if(["mute","block"].includes(action))reason=prompt(action==="mute"?"Grund für Stummschaltung":"Grund für Blockierung","")||"";
    if(action==="mod-add"&&entryIndex(p.moderators,username)<0)p.moderators.push({username,since:Date.now()});
    if(action==="mod-remove")p.moderators=p.moderators.filter(x=>x.username.toLowerCase()!==username.toLowerCase());
    if(action==="mute"&&entryIndex(p.muted,username)<0)p.muted.push({username,reason,lastMessage,since:Date.now()});
    if(action==="unmute")p.muted=p.muted.filter(x=>x.username.toLowerCase()!==username.toLowerCase());
    if(action==="block"&&entryIndex(p.blocked,username)<0)p.blocked.push({username,reason,lastMessage,since:Date.now()});
    if(action==="unblock")p.blocked=p.blocked.filter(x=>x.username.toLowerCase()!==username.toLowerCase());
    const labels={"mod-add":"Moderator hinzugefügt","mod-remove":"Moderator entfernt",mute:"Gestummt",unmute:"Entstummt",block:"Blockiert",unblock:"Entblockt"};
    addAudit(platform,username,labels[action]||action,reason,lastMessage,"Lokal");saveMod();
  }
  function isSuppressed(platform,username){const p=mod[platform];if(!p)return false;return entryIndex(p.blocked,username)>=0||entryIndex(p.muted,username)>=0;}

  function openContext(event,userEl){event.preventDefault();document.querySelector(".batto-context-menu")?.remove();const row=userEl.closest(".chat-row");const username=cleanUser(userEl.textContent);const roleText=row?.querySelector(".chat-role")?.textContent||"";const platform=PLATFORMS.find(p=>roleText.toLowerCase().includes(p))||document.querySelector(".chat-tab.active")?.dataset?.platform||"tiktok";const lastMessage=row?.querySelector(".chat-message")?.textContent||"";const menu=document.createElement("div");menu.className="batto-context-menu";menu.style.left=`${Math.min(event.clientX,window.innerWidth-270)}px`;menu.style.top=`${Math.min(event.clientY,window.innerHeight-300)}px`;menu.innerHTML=`<button data-a="mod-add">Als Moderator hinzufügen</button><button data-a="mod-remove">Als Moderator entfernen</button><hr><button data-a="mute">Stummen</button><button data-a="block">Blockieren</button><button data-a="unmute">Entstummen</button><button data-a="unblock">Entblocken</button>`;menu.querySelectorAll("button").forEach(b=>b.onclick=()=>{applyModeration(platform,username,b.dataset.a,lastMessage);menu.remove();});document.body.appendChild(menu);
  }
  document.addEventListener("contextmenu",e=>{const u=e.target.closest?.(".chat-user");if(u)openContext(e,u);});document.addEventListener("click",e=>{if(!e.target.closest?.(".batto-context-menu"))document.querySelector(".batto-context-menu")?.remove();});

  function switchCustom(name,title,subtitle){document.querySelectorAll(".view").forEach(v=>v.classList.toggle("active",v.id===`view-${name}`));document.querySelectorAll(".nav-button").forEach(b=>b.classList.toggle("active",b.dataset.view===name));const h=document.getElementById("page-title"),s=document.getElementById("page-subtitle");if(h)h.textContent=title;if(s)s.textContent=subtitle;if(name==="moderation")renderModeration();if(name==="cohost")renderCohost();}
  document.addEventListener("click",e=>{const b=e.target.closest?.("[data-custom-view]");if(!b)return;const n=b.dataset.customView;if(n==="moderation")switchCustom(n,"Moderation","TikTok, Twitch, CNG und YouTube getrennt verwalten.");if(n==="cohost")switchCustom(n,"Co-Host","OBS-Browserlayouts für TikTok- und Twitch-Format.");});

  function renderModeration(){const host=document.getElementById("view-moderation");if(!host)return;const p=mod[selectedPlatform]||emptyPlatform();const list=(items,action,label)=>items.length?items.map(x=>`<div class="mod-list-row"><div><strong>${esc(x.username)}</strong>${x.reason?`<small>${esc(x.reason)}</small>`:""}${x.lastMessage?`<small>Letzte Nachricht: ${esc(x.lastMessage)}</small>`:""}</div><button class="td-button" data-mod-user="${esc(x.username)}" data-mod-action="${action}">${label}</button></div>`).join(""):'<p class="result-copy">Keine Einträge.</p>';
    host.innerHTML=`<div class="section-heading"><div><span class="eyebrow">GETRENNT NACH PLATTFORM</span><h2>Moderation</h2><p>Rechtsklick auf einen Namen im Multi-Chat öffnet die Moderationsaktionen.</p></div></div><div class="mod-dashboard"><div class="mod-platform-tabs">${PLATFORMS.map(x=>`<button class="td-button ${x===selectedPlatform?"active":""}" data-mod-platform="${x}">${x==="cng"?"CNG":x[0].toUpperCase()+x.slice(1)}</button>`).join("")}</div><div class="mod-columns"><article class="panel mod-list"><h3>Moderatoren</h3>${list(p.moderators,"mod-remove","Entfernen")}</article><article class="panel mod-list"><h3>Stummgeschaltet</h3>${list(p.muted,"unmute","Entstummen")}</article><article class="panel mod-list"><h3>Blockiert</h3>${list(p.blocked,"unblock","Entblocken")}</article></div><article class="panel mod-audit"><h3>Moderationsverlauf</h3><table><thead><tr><th>Zeit</th><th>Name</th><th>Aktion</th><th>Grund</th><th>Letzte Nachricht</th><th>Durch</th><th>Ergebnis</th></tr></thead><tbody>${p.audit.map(a=>`<tr><td>${new Date(a.time).toLocaleString("de-DE")}</td><td>${esc(a.username)}</td><td>${esc(a.action)}</td><td>${esc(a.reason)}</td><td>${esc(a.lastMessage)}</td><td>${esc(a.by)}</td><td>${esc(a.result)}</td></tr>`).join("")||'<tr><td colspan="7">Noch keine Aktionen.</td></tr>'}</tbody></table></article></div>`;
    host.querySelectorAll("[data-mod-platform]").forEach(b=>b.onclick=()=>{selectedPlatform=b.dataset.modPlatform;renderModeration();});host.querySelectorAll("[data-mod-action]").forEach(b=>b.onclick=()=>applyModeration(selectedPlatform,b.dataset.modUser,b.dataset.modAction,""));
  }

  function injectTikfinitySettings(){const settings=document.querySelector(".chat-settings");if(!settings||settings.querySelector("#batto-tikfinity-card"))return;const card=document.createElement("div");card.id="batto-tikfinity-card";card.className="settings-section tikfinity-card";card.innerHTML=`<h3>TikFinity lokal · ohne Euler-Key</h3><div>WebSocket: <code>${TIKFINITY_URL}</code></div><strong id="tikfinity-state" class="tikfinity-state ${tikfinityConnected?"on":"off"}">${tikfinityConnected?"Verbunden":"Getrennt"}</strong><div class="settings-actions"><button id="tikfinity-connect">TikFinity verbinden</button><button id="tikfinity-disconnect">Trennen</button></div><small>TikFinity Desktop muss auf demselben PC laufen und mit deinem TikTok LIVE verbunden sein.</small>`;settings.prepend(card);card.querySelector("#tikfinity-connect").onclick=connectTikfinity;card.querySelector("#tikfinity-disconnect").onclick=disconnectTikfinity;}
  const observer=new MutationObserver(()=>injectTikfinitySettings());observer.observe(document.documentElement,{subtree:true,childList:true});

  function setTikState(on,text){tikfinityConnected=on;const el=document.getElementById("tikfinity-state");if(el){el.className=`tikfinity-state ${on?"on":"off"}`;el.textContent=text|| (on?"Verbunden":"Getrennt");}}
  function connectTikfinity(){disconnectTikfinity();setTikState(false,"Verbinde …");try{tikfinity=new WebSocket(TIKFINITY_URL);tikfinity.onopen=()=>setTikState(true,"Verbunden");tikfinity.onclose=()=>setTikState(false,"Getrennt");tikfinity.onerror=()=>setTikState(false,"TikFinity nicht erreichbar");tikfinity.onmessage=e=>handleTikfinity(e.data);}catch(e){setTikState(false,e.message||"Fehler");}}
  function disconnectTikfinity(){try{tikfinity?.close();}catch{}tikfinity=null;setTikState(false,"Getrennt");}
  function pick(obj,...keys){for(const k of keys){if(obj?.[k]!==undefined&&obj[k]!==null)return obj[k];}return"";}
  function handleTikfinity(raw){let packet;try{packet=JSON.parse(String(raw));}catch{return;}const event=String(packet.event||packet.type||"").toLowerCase();const d=packet.data||packet;if(!["chat","comment"].includes(event))return;const username=cleanUser(pick(d,"uniqueId","username","nickname","displayName","userId")||"TikTok User");const message=String(pick(d,"comment","message","text")||"");if(!message||isSuppressed("tiktok",username))return;appendTikfinityChat(username,message,d);}
  function appendTikfinityChat(username,message,data){const body=document.querySelector("#multi-chat-root #chat-body");if(!body)return;body.querySelector(".chat-empty")?.remove();const row=document.createElement("div");row.className="chat-row";row.dataset.source="tikfinity";row.innerHTML=`<span class="platform-badge" style="background:#111">♪</span><div><div class="chat-meta"><span class="chat-user">${esc(username)}</span><span class="chat-role">TikTok</span><span class="chat-role">TikFinity</span></div><div class="chat-message">${esc(message)}</div></div>`;body.appendChild(row);body.scrollTop=body.scrollHeight;}

  function cohostSources(){return Array.from({length:8},(_,i)=>document.getElementById(`cohost-source-${i+1}`)?.value||"");}
  function overlayUrl(format,slots,sources){const base=`http://127.0.0.1:48621/cohost-${format}.html`;const q=new URLSearchParams({slots:String(slots)});sources.slice(0,slots).forEach((u,i)=>{if(u)q.set(`u${i+1}`,u)});return `${base}?${q}`;}
  function renderCohost(){const host=document.getElementById("view-cohost");if(!host)return;const saved=JSON.parse(localStorage.getItem("batto-cohost-v1")||"null")||{format:"tiktok",slots:4,sources:Array(8).fill("")};host.innerHTML=`<div class="section-heading"><div><span class="eyebrow">OBS-BROWSERQUELLE</span><h2>Co-Host</h2><p>Plätze frei einstellen und als TikTok-Hochformat oder Twitch-Querformat in OBS einbinden.</p></div></div><div class="cohost-layout" style="display:grid;grid-template-columns:420px 1fr;gap:16px"><article class="panel form-panel"><label>Format<select id="cohost-format"><option value="tiktok" ${saved.format==="tiktok"?"selected":""}>TikTok · 1080 × 1920</option><option value="twitch" ${saved.format==="twitch"?"selected":""}>Twitch · 1920 × 1080</option></select></label><label>Plätze<select id="cohost-slots">${[1,2,3,4,5,6,7,8].map(n=>`<option ${saved.slots===n?"selected":""}>${n}</option>`).join("")}</select></label><div class="cohost-sources">${Array.from({length:8},(_,i)=>`<label>Platz ${i+1}<input id="cohost-source-${i+1}" value="${esc(saved.sources?.[i]||"")}" placeholder="Browser-/Gast-URL"></label>`).join("")}</div><div class="button-row"><button class="primary" id="cohost-apply">Übernehmen</button><button id="cohost-copy">OBS-Adresse kopieren</button></div><div class="url-bar"><span>OBS</span><code id="cohost-url" class="cohost-url"></code></div></article><article class="panel"><h3>Vorschau der Platzaufteilung</h3><div id="cohost-preview"></div></article></div>`;const update=()=>{const format=document.getElementById("cohost-format").value,slots=Number(document.getElementById("cohost-slots").value);const preview=document.getElementById("cohost-preview");const cols=slots<=1?1:slots<=4?2:3;preview.className=`cohost-grid-preview ${format}`;preview.style.gridTemplateColumns=`repeat(${cols},1fr)`;preview.innerHTML=Array.from({length:slots},(_,i)=>`<div class="cohost-slot">Gast ${i+1}</div>`).join("");document.getElementById("cohost-url").textContent=overlayUrl(format,slots,cohostSources());};document.getElementById("cohost-format").onchange=update;document.getElementById("cohost-slots").onchange=update;host.querySelectorAll("[id^=cohost-source]").forEach(x=>x.oninput=update);document.getElementById("cohost-apply").onclick=()=>{const cfg={format:document.getElementById("cohost-format").value,slots:Number(document.getElementById("cohost-slots").value),sources:cohostSources()};localStorage.setItem("batto-cohost-v1",JSON.stringify(cfg));update();};document.getElementById("cohost-copy").onclick=async()=>{update();try{await navigator.clipboard.writeText(document.getElementById("cohost-url").textContent);}catch{}};update();}

  window.addEventListener("beforeunload",disconnectTikfinity);
  renderModeration();
})();